typedef long long ll;

static ll maxll(ll a, ll b) { return a > b ? a : b; }

int main(void) {
    int R, C, K;
    if (scanf("%d %d %d", &R, &C, &K) != 3) return 0;

    ll *val = (ll *)calloc((size_t)(R + 1) * (C + 1), sizeof(ll));
    if (!val) return 0;

    for (int i = 0; i < K; i++) {
        int r, c;
        ll v;
        scanf("%d %d %lld", &r, &c, &v);
        val[(size_t)r * (C + 1) + c] = v;
    }

    /* dp[j][k]:
       after processing current cell in current row up to column j,
       being at column j, with k items already taken in this row (0..3),
       maximum total value.
    */
    ll (*dp)[4] = malloc((size_t)(C + 1) * sizeof(*dp));
    ll (*ndp)[4] = malloc((size_t)(C + 1) * sizeof(*ndp));
    if (!dp || !ndp) return 0;

    const ll NEG = -(1LL << 60);

    for (int j = 0; j <= C; j++) {
        for (int k = 0; k < 4; k++) dp[j][k] = NEG;
    }
    dp[0][0] = 0;

    for (int i = 1; i <= R; i++) {
        for (int j = 0; j <= C; j++) {
            for (int k = 0; k < 4; k++) ndp[j][k] = NEG;
        }

        for (int j = 1; j <= C; j++) {
            ll w = val[(size_t)i * (C + 1) + j];

            /* Come from above: row count resets */
            ll best_up = NEG;
            for (int k = 0; k < 4; k++) best_up = maxll(best_up, dp[j][k]);

            ndp[j][0] = maxll(ndp[j][0], best_up);
            if (w > 0) ndp[j][1] = maxll(ndp[j][1], best_up + w);

            /* Come from left: stay in same row */
            for (int k = 0; k < 4; k++) {
                ndp[j][k] = maxll(ndp[j][k], ndp[j - 1][k]);
                if (k < 3 && w > 0) {
                    ndp[j][k + 1] = maxll(ndp[j][k + 1], ndp[j - 1][k] + w);
                }
            }
        }

        ll (*tmp)[4] = dp;
        dp = ndp;
        ndp = tmp;
    }

    ll ans = 0;
    for (int k = 0; k < 4; k++) ans = maxll(ans, dp[C][k]);
    printf("%lld\n", ans);

    free(val);
    free(dp);
    free(ndp);
    return 0;
}

