int main(){
    int R, C, K;
    cin >> R >> C >> K;

    vector<vector<pair<int,int>>> items(R+1); // items[row] = {col, val}
    for(int i=0;i<K;i++){
        int r,c,v; cin>>r>>c>>v;
        items[r].push_back({c,v});
    }

    // dp[c] = max value when exiting current row at column c
    // Use map for sparse columns
    map<int,long long> dp;
    dp[1] = 0; // start at row 1, entered at col 1

    for(int r=1;r<=R;r++){
        auto& row = items[r];
        sort(row.begin(), row.end());

        // Get all relevant exit columns: item cols + col C (if last row) + col 1 (if first row already handled)
        set<int> exits_set;
        for(auto&p:row) exits_set.insert(p.first);
        if(r==R) exits_set.insert(C);
        else { for(auto&p:row) exits_set.insert(p.first); }
        // Also carry forward entry columns as possible exits
        for(auto&p:dp) exits_set.insert(p.first);
        if(r<R) {} // exit can be any col >= entry
        exits_set.insert(C); // always valid to exit at C? only if r==R
        // Actually exit col must be reachable: any col from 1 to C
        // But we only need cols where something interesting happens

        map<int,long long> ndp;
        vector<int> exits(exits_set.begin(), exits_set.end());

        for(int ex : exits){
            long long best = LLONG_MIN/2;
            for(auto&[en, val]:dp){
                if(en > ex) continue;
                // best 3 items in row r with col in [en, ex]
                vector<int> vals;
                for(auto&[ic,iv]:row) if(ic>=en && ic<=ex) vals.push_back(iv);
                sort(vals.rbegin(),vals.rend());
                long long add=0; for(int i=0;i<min(3,(int)vals.size());i++) add+=vals[i];
                best=max(best, val+add);
            }
            if(best>LLONG_MIN/2) ndp[ex]=max(ndp[ex],best);
        }
        dp=ndp;
    }

    cout << (dp.count(C)?dp[C]:0) << endl;
}

