        int r, c;
        long long v;
        cin >> r >> c >> v;
        val[r][c] = v;
    }

    const long long NEG = -(1LL << 60);

    // dp[j][k]:
    // while processing current row, at column j,
    // maximum value when we are at (current_row, j)
    // having picked k items in the current row so far.
    vector<array<long long, 4>> dp(C + 1), ndp(C + 1);

    for (int j = 0; j <= C; ++j) {
        for (int k = 0; k < 4; ++k) dp[j][k] = NEG;
    }
    dp[0][0] = 0;

    for (int i = 1; i <= R; ++i) {
        for (int j = 0; j <= C; ++j) {
            for (int k = 0; k < 4; ++k) ndp[j][k] = NEG;
        }

        for (int j = 1; j <= C; ++j) {
            long long best_from_up = NEG;

            // Come from above into (i, j): item count in this row resets to 0
            for (int k = 0; k < 4; ++k) {
                best_from_up = max(best_from_up, dp[j][k]);
            }
            ndp[j][0] = max(ndp[j][0], best_from_up);
            if (val[i][j] > 0) {
                ndp[j][1] = max(ndp[j][1], best_from_up + val[i][j]);
            }

            // Come from left within the same row
            for (int k = 0; k < 4; ++k) {
                ndp[j][k] = max(ndp[j][k], ndp[j - 1][k]); // don't take item here
            }
            if (val[i][j] > 0) {
                for (int k = 0; k < 3; ++k) {
                    ndp[j][k + 1] = max(ndp[j][k + 1], ndp[j - 1][k] + val[i][j]);
                }
            }
        }

        dp.swap(ndp);
    }

    long long ans = 0;
    for (int k = 0; k < 4; ++k) ans = max(ans, dp[C][k]);
    cout << ans << '\n';
    return 0;
}

