            for (int c = 1; c <= C; c++) {
                // carry over from top
                for (int k = 0; k <= 3; k++) {
                    dp[r][c][k] = Math.max(dp[r][c][k], dp[r - 1][c][k]);
                }
                // carry over from left
                for (int k = 0; k <= 3; k++) {
