public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int R = sc.nextInt(), C = sc.nextInt(), K = sc.nextInt();
        List<int[]>[] rowItems = new List[R + 1];
        for (int i = 1; i <= R; i++) rowItems[i] = new ArrayList<>();
        for (int i = 0; i < K; i++) {
            int r = sc.nextInt(), c = sc.nextInt(), v = sc.nextInt();
            rowItems[r].add(new int[]{c, v});
        }
        for (int i = 1; i <= R; i++) rowItems[i].sort((a, b) -> a[0] - b[0]);

        long[] dp = new long[C + 1];
        long NEG = Long.MIN_VALUE / 2;
        Arrays.fill(dp, NEG);
        dp[1] = 0;

        for (int r = 1; r <= R; r++) {
            long[] ndp = new long[C + 1];
            Arrays.fill(ndp, NEG);
            List<int[]> items = rowItems[r];
            for (int b = 1; b <= C; b++) {
                long[] top3 = new long[]{0, 0, 0};
                // sliding from b down to 1, adding items
                // For entry a, exit b: items with col in [a,b]
                // We go a from b down to 1
                int ptr = items.size() - 1;
                while (ptr >= 0 && items.get(ptr)[0] > b) ptr--;
                // items[0..ptr] have col <= b
                // as a decreases, we include more items from the left
                long[] cur = new long[]{0,0,0};
                int leftPtr = ptr;
                for (int a = b; a >= 1; a--) {
                    // add items with col == a
                    while (leftPtr >= 0 && items.get(leftPtr)[0] >= a) {
                        // insert items.get(leftPtr)[1] into cur top3
                        long val = items.get(leftPtr)[1];
                        if (val > cur[0]) { cur[2]=cur[1]; cur[1]=cur[0]; cur[0]=val; }
                        else if (val > cur[1]) { cur[2]=cur[1]; cur[1]=val; }
                        else if (val > cur[2]) { cur[2]=val; }
                        leftPtr--;
                    }
                    if (dp[a] != NEG) {
                        long best = dp[a] + cur[0] + cur[1] + cur[2];
                        if (best > ndp[b]) ndp[b] = best;
                    }
                }
            }
            dp = ndp;
        }
        System.out.println(dp[C]);
    }
}

