public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int R = fs.nextInt();
        int C = fs.nextInt();
        int K = fs.nextInt();

        long[][] value = new long[R + 1][C + 1];
        for (int i = 0; i < K; i++) {
            int r = fs.nextInt();
            int c = fs.nextInt();
            long v = fs.nextLong();
            value[r][c] = v;
        }

        // dp[j][t]:
        // after processing current cell in current row at column j,
        // maximum value when we are at (currentRow, j) and have taken t items in this row
        long[][] dp = new long[C + 1][4];
        long NEG = -(1L << 60);

        for (int j = 0; j <= C; j++) {
            Arrays.fill(dp[j], NEG);
        }

        for (int i = 1; i <= R; i++) {
            long[] fromUp = new long[C + 1];

            // Build values when entering row i from above.
            for (int j = 1; j <= C; j++) {
                long best = NEG;
                for (int t = 0; t < 4; t++) best = Math.max(best, dp[j][t]);
                fromUp[j] = best;
            }

            long[][] ndp = new long[C + 1][4];
            for (int j = 0; j <= C; j++) {
                Arrays.fill(ndp[j], NEG);
            }

            for (int j = 1; j <= C; j++) {
                long v = value[i][j];

                // Come from left within the same row
                for (int t = 0; t < 4; t++) {
                    ndp[j][t] = Math.max(ndp[j][t], ndp[j - 1][t]);
                }
                if (v > 0) {
                    for (int t = 0; t < 3; t++) {
                        if (ndp[j - 1][t] != NEG) {
                            ndp[j][t + 1] = Math.max(ndp[j][t + 1], ndp[j - 1][t] + v);
                        }
                    }
                }

                // Come from above: item count in this row resets
                ndp[j][0] = Math.max(ndp[j][0], fromUp[j]);
                if (v > 0 && fromUp[j] != NEG) {
                    ndp[j][1] = Math.max(ndp[j][1], fromUp[j] + v);
                }

                // Special handling for start cell (1,1)
                if (i == 1 && j == 1) {
                    ndp[j][0] = Math.max(ndp[j][0], 0);
                    if (v > 0) ndp[j][1] = Math.max(ndp[j][1], v);
                }
            }

            dp = ndp;
        }

        long ans = 0;
        for (int t = 0; t < 4; t++) ans = Math.max(ans, dp[C][t]);
        System.out.println(ans);
    }
}

import sys

def main():
    input = sys.stdin.readline
    R, C, K = map(int, input().split())

    # value[r][c] = item value at cell (r, c), 1-indexed
    value = [[0] * (C + 1) for _ in range(R + 1)]
    for _ in range(K):
        r, c, v = map(int, input().split())
        value[r][c] = v

    NEG = -10**18

    # dp[j][k]:
    # while processing current row, after reaching column j,
    # having picked k items in this row so far (k = 0..3),
    # maximum total value.
    dp = [[NEG] * 4 for _ in range(C + 1)]
    dp[1][0] = 0

    for i in range(1, R + 1):
        ndp = [[NEG] * 4 for _ in range(C + 1)]

        for j in range(1, C + 1):
            v = value[i][j]

            # Come from above:
            # when entering a new row, picked count in this row resets to 0
            best_from_above = max(dp[j])
            if best_from_above > ndp[j][0]:
                ndp[j][0] = best_from_above
            if v > 0 and best_from_above + v > ndp[j][1]:
                ndp[j][1] = best_from_above + v

            # Come from left within same row
            if j > 1:
                for k in range(4):
                    if ndp[j - 1][k] > ndp[j][k]:
                        ndp[j][k] = ndp[j - 1][k]
                if v > 0:
                    for k in range(3):
                        if ndp[j - 1][k] + v > ndp[j][k + 1]:
                            ndp[j][k + 1] = ndp[j - 1][k] + v

        dp = ndp

    print(max(dp[C]))

